import json,re
d=json.load(open('liquidglass.json'))
out=[]
def walk(n):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c)
            return
        elif t=='codeVoice': out.append(n.get('code',''))
        for k,v in n.items():
            if k in ('text','type','code'): continue
            walk(v)
    elif isinstance(n,list):
        for i in n: walk(i)
walk(d)
s=''.join(out)
open('lg.txt','w').write(s)
print(len(s))
"
